import {
  BufferTarget,
  CanvasSource,
  getFirstEncodableVideoCodec,
  Mp4OutputFormat,
  Output,
  OutputFormat,
  Quality,
  WebMOutputFormat,
  type VideoCodec,
} from "mediabunny";
import type { EvaluatedFrame } from "../core/frameEvaluator";
import { renderFrame } from "../core/renderer";
import { createBrowserBlurHost } from "./browserBlurHost";
import type { DisplayMode } from "../shared/sceneSchema";

export type VideoRecorderFormat = "webm" | "mp4";

// VP9 keeps the quality/size balance the previous MediaRecorder path had; VP8
// stays available for leaner WebCodecs implementations that reject VP9.
// AVC (H.264) is preferred for MP4 output to ensure compatibility with SNS (X).
const kWebmCodecCandidates: VideoCodec[] = ["vp9", "vp8"];
const kMp4CodecCandidates: VideoCodec[] = ["avc", "vp9", "vp8"];
const kQuality = new Quality("high");
// Recording pushes frames as fast as they evaluate and waits on the encoder for
// each one, so encoder throughput sets how long a capture takes. The default
// 'no-preference' lets the implementation pick, and a software VP9 encoder is
// slow enough to dominate the whole recording.
//
// The hint cannot simply be set, because a host with no matching hardware
// encoder rejects the configuration outright rather than falling back, which
// would turn a slow recording into an impossible one. Probe it first and only
// ask for hardware where the encoder says it can deliver.
const kPreferredAcceleration: HardwareAcceleration = "prefer-hardware";

async function resolveHardwareAcceleration(
  codec: VideoCodec,
  width: number,
  height: number,
  frameRate: number,
): Promise<HardwareAcceleration> {
  if (typeof VideoEncoder === "undefined" || VideoEncoder.isConfigSupported === undefined) {
    return "no-preference";
  }
  try {
    const support = await VideoEncoder.isConfigSupported({
      codec: kProbeCodecStrings[codec] ?? codec,
      width,
      height,
      framerate: frameRate,
      hardwareAcceleration: kPreferredAcceleration,
    });
    return support.supported === true ? kPreferredAcceleration : "no-preference";
  } catch {
    // A host that rejects the probe outright cannot honour the hint either.
    return "no-preference";
  }
}

// Minimal codec strings for the support probe. The real encoder string is built
// by the library from the same codec id; these only need to be specific enough
// for isConfigSupported to answer.
const kProbeCodecStrings: Partial<Record<VideoCodec, string>> = {
  vp9: "vp09.00.10.08",
  vp8: "vp8",
  avc: "avc1.42001f",
};
// Frequent key frames cost size but keep scrubbing responsive, which matters
// more for short preview clips than for long-form video.
const kKeyFrameIntervalSeconds = 1;

// Encodes evaluated frames into a WebM or MP4 blob through WebCodecs. Frames are
// rendered onto an offscreen canvas at the scene's native pixel size, so the
// output resolution is independent of the preview panel size and zoom.
//
// Unlike a MediaRecorder capture this is not bound to wall-clock time:
// timestamps come from the frame index, so the caller may push frames as fast
// as it can evaluate them and the result still plays at the scene frame rate.
export class VideoRecorder {
  private readonly context: CanvasRenderingContext2D;
  private readonly blurHost = createBrowserBlurHost();
  private readonly output: Output<OutputFormat, BufferTarget>;
  private readonly source: CanvasSource;
  private readonly frameDurationSeconds: number;
  private encodedFrameCount = 0;

  static isSupported(): boolean {
    return typeof VideoEncoder !== "undefined" && typeof VideoFrame !== "undefined";
  }

  // Async because codec support and the output header can only be resolved by
  // querying the browser's encoder.
  static async create(
    canvasWidth: number,
    canvasHeight: number,
    fps: number,
    format: VideoRecorderFormat = "webm",
  ): Promise<VideoRecorder> {
    if (!VideoRecorder.isSupported()) {
      throw new Error("Video recording requires WebCodecs support");
    }
    const width = Math.max(Math.round(canvasWidth), 1);
    const height = Math.max(Math.round(canvasHeight), 1);
    const frameRate = Math.max(fps, 0.001);
    const codecCandidates = format === "mp4" ? kMp4CodecCandidates : kWebmCodecCandidates;
    const codec = await getFirstEncodableVideoCodec(codecCandidates, {
      width,
      height,
      quality: kQuality,
    });
    if (codec === null) {
      throw new Error(`no supported video codec is available for ${format}`);
    }
    const outputFormat = format === "mp4" ? new Mp4OutputFormat() : new WebMOutputFormat();
    const hardwareAcceleration = await resolveHardwareAcceleration(codec, width, height, frameRate);
    const recorder = new VideoRecorder(
      width,
      height,
      frameRate,
      codec,
      outputFormat,
      hardwareAcceleration,
    );
    await recorder.output.start();
    return recorder;
  }

  private constructor(
    width: number,
    height: number,
    frameRate: number,
    codec: VideoCodec,
    outputFormat: OutputFormat,
    hardwareAcceleration: HardwareAcceleration,
  ) {
    this.frameDurationSeconds = 1 / frameRate;
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d");
    if (context === null) {
      throw new Error("2D canvas context unavailable for recording");
    }
    this.context = context;
    this.output = new Output({
      format: outputFormat,
      target: new BufferTarget(),
    });
    this.source = new CanvasSource(canvas, {
      codec,
      quality: kQuality,
      keyFrameInterval: kKeyFrameIntervalSeconds,
      hardwareAcceleration,
    });
    this.output.addVideoTrack(this.source, { frameRate });
  }

  // Renders and encodes one frame. Awaiting the returned promise applies the
  // encoder's own backpressure, so the queue cannot grow without bound.
  async captureFrame(
    frame: EvaluatedFrame,
    displayMode: DisplayMode,
    showIndexLabels: boolean,
  ): Promise<void> {
    renderFrame(this.context, frame, 1, { displayMode, showIndexLabels, blur: this.blurHost });
    const timestamp = this.encodedFrameCount * this.frameDurationSeconds;
    this.encodedFrameCount += 1;
    await this.source.add(timestamp, this.frameDurationSeconds);
  }

  async stop(): Promise<Blob> {
    await this.output.finalize();
    const buffer = this.output.target.buffer;
    if (buffer === null) {
      throw new Error("recording produced no data");
    }
    return new Blob([buffer], { type: this.output.format.mimeType });
  }

  // Releases encoder resources without producing a file, for aborted runs.
  async dispose(): Promise<void> {
    if (this.output.state !== "finalized" && this.output.state !== "canceled") {
      await this.output.cancel();
    }
  }
}
